import os, re, sqlite3, secrets, hashlib, hmac
from datetime import date
from functools import wraps
from flask import Flask, g, render_template, request, redirect, url_for, session, flash, abort, current_app, jsonify
from werkzeug.security import generate_password_hash, check_password_hash
from werkzeug.utils import secure_filename

ROLES = ('STUDENT','STAFF','DH_MANAGER','ADMIN')
TRANSITIONS = {'PENDING': {'ACCEPTED','REJECTED','CANCELLED'}, 'ACCEPTED': {'PREPARING','CANCELLED'}, 'PREPARING': {'READY'}, 'READY': {'COMPLETED'}}
CANCELLATION_REASONS = (
    'Item unavailable',
    'Insufficient stock',
    'Outlet closing soon',
    'Unable to fulfill order',
)
ACTIVE_PREP_STATUSES = ('PENDING', 'ACCEPTED', 'PREPARING')
PREP_LANES = 2

def create_app(test_config=None):
    app=Flask(__name__)
    app.config.from_object('config.Config')
    if test_config: app.config.update(test_config)
    for key in ('DATABASE_PATH','UPLOAD_FOLDER'):
        p=app.config[key]
        if not os.path.isabs(p): app.config[key]=os.path.join(app.root_path,'..',p)
        os.makedirs(os.path.dirname(app.config[key]) if key=='DATABASE_PATH' else app.config[key],exist_ok=True)
    # Initialize the schema and apply small, idempotent upgrades on startup so
    # an existing local SQLite database remains usable after an application update.
    with app.app_context():
        init_db()
    @app.before_request
    def csrf_setup():
        if 'csrf' not in session: session['csrf']=secrets.token_urlsafe(24)
        if request.method=='POST' and not hmac.compare_digest(request.form.get('csrf_token',''),session['csrf']): abort(400,'Invalid CSRF token')
        g.user=get_db().execute('SELECT * FROM users WHERE id=? AND active=1',(session.get('user_id'),)).fetchone() if session.get('user_id') else None
    @app.context_processor
    def inject():
        unread=0
        if g.get('user'): unread=get_db().execute('SELECT count(*) FROM notifications WHERE user_id=? AND is_read=0',(g.user['id'],)).fetchone()[0]
        return {'current_user':g.get('user'),'unread_count':unread,'csrf_token':session.get('csrf','')}
    @app.teardown_appcontext
    def close_db(exc):
        db=g.pop('db',None)
        if db is not None: db.close()
    @app.cli.command('init-db')
    def init_db_cmd(): init_db(); print('Database initialized.')
    @app.route('/')
    def index():
        if not g.user: return redirect(url_for('login'))
        return redirect(url_for('dashboard'))
    @app.route('/register',methods=['GET','POST'])
    def register():
        if request.method=='POST':
            name=request.form.get('name','').strip(); email=request.form.get('email','').strip().lower(); pw=request.form.get('password','')
            if not name or len(pw)<8 or not is_krea_email(email):
                flash('Use your university email and a password of at least 8 characters.','error')
            elif get_db().execute('SELECT 1 FROM users WHERE email=?',(email,)).fetchone(): flash('An account with that email already exists.','error')
            else:
                cur=get_db().execute('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,? ,?)',(name,email,generate_password_hash(pw),'STUDENT')); get_db().commit(); audit(cur.lastrowid,'REGISTER','user',cur.lastrowid,'Student self-registration'); flash('Account created. Please sign in.','success'); return redirect(url_for('login'))
        return render_template('auth.html',register=True)
    @app.route('/login',methods=['GET','POST'])
    def login():
        if request.method=='POST':
            email=request.form.get('email','').strip().lower(); user=get_db().execute('SELECT * FROM users WHERE email=?',(email,)).fetchone()
            if not user or (user['role']=='STUDENT' and not is_krea_email(email)) or not check_password_hash(user['password_hash'],request.form.get('password','')) or not user['active']:
                audit(user['id'] if user else None,'LOGIN_FAILURE','user',user['id'] if user else None,'Invalid credentials or inactive account'); flash('Sign-in failed. Check your details or account status.','error')
            else:
                session.clear(); session['csrf']=secrets.token_urlsafe(24); session['user_id']=user['id']; audit(user['id'],'LOGIN','user',user['id'],'Successful login'); return redirect(url_for('dashboard'))
        return render_template('auth.html',register=False)
    @app.post('/logout')
    def logout(): session.clear(); flash('Signed out.','success'); return redirect(url_for('login'))
    @app.errorhandler(403)
    def forbidden(e): return render_template('error.html',code=403,message='You do not have access to this page.'),403
    @app.errorhandler(404)
    def missing(e): return render_template('error.html',code=404,message='That page or record could not be found.'),404
    @app.route('/dashboard')
