        if u['role']=='STUDENT':
            orders=get_db().execute('SELECT o.*,x.name outlet_name FROM orders o JOIN outlets x ON x.id=o.outlet_id WHERE user_id=? ORDER BY o.id DESC LIMIT 5',(u['id'],)).fetchall()
            outlets=get_db().execute('SELECT * FROM outlets WHERE active=1 ORDER BY name').fetchall()
            return render_template('student_dashboard.html',orders=orders,outlets=outlets)
        scope=outlet_scope(u); db=get_db(); cond=''; args=[]; raw_cond=''
        if scope is not None: cond=' WHERE o.outlet_id=?'; raw_cond=' WHERE outlet_id=?'; args=[scope]
        counts={s:db.execute('SELECT count(*) FROM orders'+raw_cond+(' AND' if raw_cond else ' WHERE')+' status=?',args+[s]).fetchone()[0] for s in ('PENDING','PREPARING','READY','COMPLETED','REJECTED')}
        today=db.execute('SELECT count(*) FROM orders'+raw_cond+(' AND' if raw_cond else ' WHERE')+' date(created_at)=?',args+[date.today().isoformat()]).fetchone()[0]
        orders=db.execute('SELECT o.*,u.name student,x.name outlet_name FROM orders o JOIN users u ON u.id=o.user_id JOIN outlets x ON x.id=o.outlet_id'+cond+' ORDER BY o.id DESC LIMIT 12',args).fetchall()
        low=db.execute('SELECT * FROM inventory_items WHERE active=1 AND quantity<=low_threshold'+(' AND outlet_id=?' if scope is not None else ''),( [scope] if scope is not None else [])).fetchall()
        return render_template('dashboard.html',counts=counts,today=today,orders=orders,low=low,scope=scope)
