    get_db().execute('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details,ip_address) VALUES(?,?,?,?,?,?)',(actor,action,entity,eid,str(details),request.remote_addr if request else None)); get_db().commit()
def notify(uid,title,message,kind='info'):
    get_db().execute('INSERT INTO notifications(user_id,title,message,kind) VALUES(?,?,?,?)',(uid,title,message,kind))
