PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('STUDENT','STAFF','DH_MANAGER','ADMIN')), outlet_id INTEGER REFERENCES outlets(id), active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS outlets(id INTEGER PRIMARY KEY, name TEXT NOT NULL UNIQUE, description TEXT DEFAULT '', active INTEGER NOT NULL DEFAULT 1, menu_pdf TEXT);
CREATE TABLE IF NOT EXISTS menu_categories(id INTEGER PRIMARY KEY, outlet_id INTEGER NOT NULL REFERENCES outlets(id), name TEXT NOT NULL, UNIQUE(outlet_id,name));
CREATE TABLE IF NOT EXISTS menu_items(id INTEGER PRIMARY KEY, outlet_id INTEGER NOT NULL REFERENCES outlets(id), category_id INTEGER REFERENCES menu_categories(id), name TEXT NOT NULL, description TEXT DEFAULT '', price_cents INTEGER NOT NULL CHECK(price_cents>=0), prep_minutes INTEGER NOT NULL DEFAULT 10, available INTEGER NOT NULL DEFAULT 1, inventory_id INTEGER REFERENCES inventory_items(id), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inventory_items(id INTEGER PRIMARY KEY, outlet_id INTEGER NOT NULL REFERENCES outlets(id), item_name TEXT NOT NULL, quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0), unit TEXT NOT NULL DEFAULT 'portion', low_threshold INTEGER NOT NULL DEFAULT 5, active INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(outlet_id,item_name));
CREATE TABLE IF NOT EXISTS inventory_adjustments(id INTEGER PRIMARY KEY, inventory_id INTEGER NOT NULL REFERENCES inventory_items(id), actor_id INTEGER REFERENCES users(id), delta INTEGER NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, order_number TEXT NOT NULL UNIQUE, user_id INTEGER NOT NULL REFERENCES users(id), outlet_id INTEGER NOT NULL REFERENCES outlets(id), status TEXT NOT NULL CHECK(status IN ('PENDING','ACCEPTED','PREPARING','READY','COMPLETED','REJECTED','CANCELLED')), payment_method TEXT NOT NULL, payment_status TEXT NOT NULL, total_cents INTEGER NOT NULL, prep_minutes INTEGER NOT NULL, cancellation_reason TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS order_items(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES orders(id), menu_item_id INTEGER NOT NULL REFERENCES menu_items(id), item_name TEXT NOT NULL, quantity INTEGER NOT NULL, unit_price_cents INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pickup_otps(order_id INTEGER PRIMARY KEY REFERENCES orders(id), otp_hash TEXT NOT NULL, used_at TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, message TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'info', is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), action TEXT NOT NULL, entity_type TEXT NOT NULL, entity_id INTEGER, details TEXT NOT NULL DEFAULT '', ip_address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS system_settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
